const s=$('When Called for CRM Context').first().json;
const one=(name)=>{try{return $(name).first().json||{};}catch(e){return{};}};
const portal=one('Read HubSpot Portal');
const companyRows=$('Find Company by Domain').all().map(i=>i.json).filter(x=>x&&(x.companyId||x.id));
const company=companyRows.length?companyRows[0]:null;
const cp=(company&&company.properties)||{};
const cv=(k)=>{const v=cp[k];return v&&typeof v==='object'?String(v.value==null?'':v.value):String(v==null?'':v);};
const companyId=company?String(company.companyId||company.id):'';
const contactRows=$('Find Contact by Email').all().map(i=>i.json).filter(x=>x&&x.id);
const contact=contactRows.length?contactRows[0]:null;
const ctp=(contact&&contact.properties)||{};
const deals=companyId?$('Find Deals by Company').all().map(i=>i.json).filter(x=>x&&x.id):[];
const closed=['closedwon','closedlost'];
const openDeals=deals.filter(d=>!closed.includes(String((d.properties&&d.properties.dealstage)||'').toLowerCase()));
const contactOwner=String(ctp.hubspot_owner_id||'');
const companyOwner=cv('hubspot_owner_id');
const ownerId=contactOwner||companyOwner||'';
const lifecycle=String(ctp.lifecyclestage||'').toLowerCase();
const customerStatus=!contact?'net_new':lifecycle==='customer'?'customer':lifecycle==='opportunity'?'open_opportunity':'known_prospect';
const portalId=String(portal.portalId||(company&&company.portalId)||'');
const contactId=contact?String(contact.id):'';
const contactUrl=contact&&contact.url?String(contact.url):(portalId&&contactId?'https://app.hubspot.com/contacts/'+portalId+'/record/0-1/'+contactId:'');
return[{json:{...s,crm_context:{lookup_status:'complete',portal_id:portalId||null,hubspot_contact_id:contactId||null,hubspot_contact_url:contactUrl||null,is_net_new:!contact,existing_contact:contact?{id:contactId,email:ctp.email||s.email||null,first_name:ctp.firstname||null,last_name:ctp.lastname||null,job_title:ctp.jobtitle||null,company:ctp.company||null,lifecycle_stage:ctp.lifecyclestage||null,lead_status:ctp.hs_lead_status||null}:null,company:companyId?{id:companyId,name:cv('name')||null,domain:cv('domain')||null,industry:cv('industry')||null,employees:cv('numberofemployees')?Number(cv('numberofemployees')):null,annual_revenue:cv('annualrevenue')||null,owner_id:companyOwner||null}:null,company_match:companyId?'domain_exact':'not_found_by_domain',owner_id:ownerId||null,owner_source:contactOwner?'contact':(companyOwner?'company':'none'),customer_status:customerStatus,open_deal:openDeals.length?{id:String(openDeals[0].id),name:(openDeals[0].properties||{}).dealname||null,stage:(openDeals[0].properties||{}).dealstage||null,amount:(openDeals[0].properties||{}).amount||null,close_date:(openDeals[0].properties||{}).closedate||null}:null,open_deal_count:openDeals.length,related_deals:openDeals.map(d=>({id:String(d.id),name:(d.properties||{}).dealname||null,stage:(d.properties||{}).dealstage||null,amount:(d.properties||{}).amount||null,close_date:(d.properties||{}).closedate||null})),warnings:[]}}}];
